insert into species (id, name, batch, art_ref, class, rank, tier, force_primary, force_secondary, role, evolution_line, stage, signature_skill, tags, description, status) values
  ('AD01', 'Ruinmaw', 'adult', 'adult#1', 'organic', 'wild', 'T2', 'Chaos', 'Thanatos', 'striker', 'Ruin Wolf', 'adult', NULL, NULL, 'Feral runed wolf; bleeds what it bites.', 'confirmed'),
