  ('AD09', 'Gloamcat', 'adult', 'adult#9', 'organic', 'wild', 'T2', 'Thanatos', 'Ouranos', 'assassin', 'Gloam Cat', 'adult', NULL, NULL, 'Soul-flame panther; drains as it strikes.', 'confirmed'),
  ('AD10', 'Thornmane', 'adult', 'adult#10', 'organic', 'wild', 'T2', 'Eros', 'Gaia', 'regenerator', 'Thorn Lion', 'adult', NULL, NULL, 'Bark-maned beast that roots and heals.', 'confirmed'),
