  ('DM02', 'Ogre-brute', 'demon', 'demon#2', 'organic', 'legendary', NULL, 'Gaia', 'Chaos', 'bruiser', NULL, 'apex', NULL, ARRAY['boss']::text[], 'All fists, no patience.', 'confirmed'),
  ('DM03', 'Bone-weaver', 'demon', 'demon#3', 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'boss', NULL, 'apex', NULL, ARRAY['undead', 'boss']::text[], 'A spider knit from someone else''s skeleton.', 'confirmed'),
  ('DM04', 'Eye-tyrant', 'demon', 'demon#4', 'organic', 'legendary', NULL, 'Chaos', 'Ouranos', 'boss', NULL, 'apex', NULL, ARRAY['secret-boss', 'eldritch']::text[], 'Sees too much, forgives nothing.', 'confirmed'),
  ('DM05', 'Phoenix', 'demon', 'demon#5', 'organic', 'god', NULL, 'Ouranos', 'Chaos', 'god-seed', NULL, 'apex', NULL, ARRAY['ascension-candidate']::text[], 'Dies on schedule, comes back annoyed.', 'confirmed'),
  ('DM06', 'Core-golem', 'demon', 'demon#6', 'organic', 'legendary', NULL, 'Gaia', 'Cosmos', 'tank', NULL, 'apex', NULL, ARRAY['boss']::text[], 'A boulder with a glowing grudge.', 'confirmed'),
