  ('DM09', 'Abyssal-leviathan', 'demon', 'demon#9', 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'boss', NULL, 'apex', NULL, ARRAY['boss']::text[], 'The deep, with teeth.', 'confirmed'),
  ('DM10', 'Elder-treant', 'demon', 'demon#10', 'organic', 'god', NULL, 'Eros', 'Gaia', 'god-seed', NULL, 'apex', NULL, ARRAY['ascension-candidate']::text[], 'Older than the forest''s first apology.', 'confirmed'),
