  ('SB28', 'Frilled-gecko', 'storybook', 'SB#28', 'organic', 'wild', 'T1', 'Ouranos', 'Eros', 'striker', 'Frill', 'mid', NULL, ARRAY['evo-of-SB18?']::text[], NULL, 'draft'),
  ('SB29', 'Griffin-cub', 'storybook', 'SB#29', 'organic', 'wild', 'T1', 'Ouranos', 'Cosmos', 'seer', 'Griffin', 'baby', NULL, ARRAY['new-species']::text[], NULL, 'confirmed'),
  ('SB30', 'Ruin-pup', 'storybook', 'SB#30', 'organic', 'wild', 'T1', 'Chaos', 'Thanatos', 'striker', 'Ruin Wolf', 'baby', NULL, NULL, 'Ruinmaw pup; chews everything.', 'confirmed'),
  ('SB31', 'Frost-kit', 'storybook', 'SB#31', 'organic', 'wild', 'T1', 'Ouranos', 'Cosmos', 'striker', 'Frost Cat', 'baby', NULL, ARRAY['new-species']::text[], NULL, 'confirmed'),
  ('SB32', 'Spore-cub', 'storybook', 'SB#32', 'organic', 'wild', 'T1', 'Gaia', 'Eros', 'tank', 'Spore Bear', 'baby', NULL, ARRAY['new-species']::text[], NULL, 'confirmed'),
  ('SB33', 'Wild-stag-calf', 'storybook', 'SB#33', 'organic', 'wild', 'T1', 'Eros', 'Gaia', 'support', 'Wild Stag', 'baby', NULL, ARRAY['new-species']::text[], NULL, 'confirmed'),
  ('S2-01', 'Sootkin', 'set2A', 'montage_set2_A #S2-1', 'organic', 'wild', 'T2', 'Thanatos', NULL, 'assassin', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A smoke-leaking kitten that has not yet grown into its body count, but is clearly saving up; adorable from the front, rehearsing worse from the back.', 'reviewed'),
  ('S2-02', 'Vesperkit', 'set2A', 'montage_set2_A #S2-2', 'organic', 'wild', 'T2', 'Thanatos', NULL, 'assassin', NULL, 'mid', NULL, ARRAY['draft']::text[], 'All bat-ears and bad news, it hears your pulse from the next room and finds it unpunctual; sits on your chest at dusk, taking notes.', 'reviewed'),
  ('S2-03', 'Scorchimp', 'set2A', 'montage_set2_A #S2-3', 'organic', 'wild', 'T2', 'Chaos', NULL, 'nuker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A pocket-sized arson with horns it has not earned and a temper it absolutely has; every flammable thing you own is, to it, kindling awaiting destiny.', 'reviewed'),
  ('S2-04', 'Harewatch', 'set2A', 'montage_set2_A #S2-4', 'organic', 'wild', 'T2', 'Cosmos', NULL, 'control', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A many-tailed hare with the patience of a thing that has already counted everyone; where it sits, the dice land flatter and the world minds its manners.', 'reviewed'),
  ('S2-05', 'Cindersmoke', 'set2A', 'montage_set2_A #S2-5', 'organic', 'wild', 'T2', 'Thanatos', NULL, 'assassin', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A kit the colour of a fire someone gave up on, with two blue coals for eyes; it does not hiss, it cools — rooms and morale drop a degree.', 'reviewed'),
  ('S2-06', 'Mothflare', 'set2A', 'montage_set2_A #S2-6', 'organic', 'wild', 'T2', 'Chaos', NULL, 'nuker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A cat that grew wings out of a campfire and the attitude to match; the wing-powder is gorgeous, combustible, and aimed at your favourite cloak.', 'reviewed'),
  ('S2-07', 'Frilltoad', 'set2A', 'montage_set2_A #S2-7', 'organic', 'wild', 'T2', 'Eros', NULL, 'support', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A fat amphibian wearing a salad it grew itself, blinking at the carnage; step on the frills and it fogs your wounds shut, its idea of an apology.', 'reviewed'),
  ('S2-08', 'Brambleshade', 'set2A', 'montage_set2_A #S2-8', 'organic', 'wild', 'T2', 'Thanatos', NULL, 'assassin', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A fox-kit knit from briar-shadow and bad grudges, one tail too many; by the time you realise the bramble has eyes, it has gone back to having none.', 'reviewed'),
  ('S2-09', 'Mourncoil', 'set2A', 'montage_set2_A #S2-9', 'organic', 'wild', 'T2', 'Thanatos', NULL, 'assassin', NULL, 'mid', NULL, ARRAY['draft']::text[], 'Half low-slung predator, half thing that should have stayed in the well, joined at a restless tail; it walks like an apology and strikes like a debt.', 'reviewed'),
  ('S2-10', 'Carapax', 'set2A', 'montage_set2_A #S2-10', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A creature built on the principle that the best argument is not moving, conducted from inside a great deal of armour; it will hold a doorway for a week.', 'reviewed'),
  ('S2-11', 'Sprydrake', 'set2A', 'montage_set2_A #S2-11', 'organic', 'wild', 'T2', 'Ouranos', NULL, 'striker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A whip-quick drake that treats gravity as a suggestion and standing still as failure; it strikes first, asks nothing, is already three feet to the left.', 'reviewed'),
  ('S2-12', 'Sablecoil', 'set2A', 'montage_set2_A #S2-12', 'organic', 'wild', 'T2', 'Thanatos', NULL, 'assassin', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A coil of drowned indigo that moves like spilled ink finding your ankles; it does not chase — it waits at the bottom of wherever the fight is sliding.', 'reviewed'),
  ('S2-13', 'Reefjaw', 'set2A', 'montage_set2_A #S2-13', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A reptile that let a reef move in rent-free until it became eighty percent fortress, twenty percent landlord; razor coral, load-bearing, and biting.', 'reviewed'),
  ('S2-14', 'Naiadrill', 'set2A', 'montage_set2_A #S2-14', 'organic', 'wild', 'T2', 'Ouranos', NULL, 'striker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A gauzy pink nothing that drifts like an unfinished thought, then darts; boneless, hurryless, and always somehow already past you.', 'reviewed'),
  ('S2-15', 'Reedotter', 'set2A', 'montage_set2_A #S2-15', 'organic', 'wild', 'T2', 'Ouranos', NULL, 'striker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A river-otter that swapped baby softness for fins and bad intentions, fast enough to mug a fish mid-thought; it strikes, vanishes, and takes your snack.', 'reviewed'),
  ('S2-16', 'Spinewyrm', 'set2A', 'montage_set2_A #S2-16', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A lump of armoured green patience with one enormous unimpressed eye and a shell coiled like an old argument; whatever it sees is not worth flinching for.', 'reviewed'),
  ('S2-17', 'Mossreliquary', 'set2A', 'montage_set2_A #S2-17', 'organic', 'wild', 'T2', 'Eros', NULL, 'support', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A patient green lizard wearing a shrine''s worth of moss; where it rests, old wounds furze over with new growth and someone always feels better.', 'reviewed'),
  ('S2-18', 'Stormcollar', 'set2A', 'montage_set2_A #S2-18', 'organic', 'wild', 'T2', 'Cosmos', NULL, 'control', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A pup wearing a collar of its own spines and a temper of low static; it does not bite first, it insulates — sending the fight''s worst to ground.', 'reviewed'),
  ('S2-19', 'Glasspup', 'set2A', 'montage_set2_A #S2-19', 'organic', 'wild', 'T2', 'Cosmos', NULL, 'control', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A soft lilac dumpling with a back-fence of crystal and the serene certainty nothing bad gets past it; lawful little rainbows, the prettiest way to say no.', 'reviewed'),
  ('S2-20', 'Spinewrack', 'set2A', 'montage_set2_A #S2-20', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A low, heavy drake that decided the answer to most threats is more spikes, closer together; hitting it is its own punishment, exactly as arranged.', 'reviewed'),
  ('S2-21', 'Riftcur', 'set2A', 'montage_set2_A #S2-21', 'organic', 'wild', 'T2', 'Chaos', NULL, 'nuker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A wolf that lost an argument with a thornbush and a curse the same night and came back meaner; every lunge costs it something it can''t afford.', 'reviewed'),
  ('S2-22', 'Barrowtusk', 'set2A', 'montage_set2_A #S2-22', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A boar caught between piglet and battering-ram, all bristle and not quite enough tusk yet; it holds ground beautifully and charges clumsily, for now.', 'reviewed'),
  ('S2-23', 'Quillkit', 'set2A', 'montage_set2_A #S2-23', 'organic', 'wild', 'T2', 'Ouranos', NULL, 'striker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A half-grown caracal built entirely out of legs and intentions, fast enough to arrive before its own shadow; strikes first, lands light, is gone.', 'reviewed'),
  ('S2-24', 'Wether-of-Wards', 'set2A', 'montage_set2_A #S2-24', 'organic', 'wild', 'T2', 'Cosmos', NULL, 'control', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A grey ram with horns wound like written law and the stare of something that has already adjudicated you; the spiral horns are a seal, taken seriously.', 'reviewed'),
  ('S2-25', 'Scalemarch', 'set2A', 'montage_set2_A #S2-25', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A long, patient lizard armoured like a roof-tile, built to march into a position and stay there; it advances at the speed of a grudge.', 'reviewed'),
  ('S2-26', 'Stonegnaw', 'set2A', 'montage_set2_A #S2-26', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A barrel of red muscle and digging claws that treats every problem as a hole to make or a wall to be; hit it all day, it''ll be busy not noticing.', 'reviewed'),
  ('S2-27', 'Stormquill', 'set2A', 'montage_set2_A #S2-27', 'organic', 'wild', 'T2', 'Ouranos', NULL, 'striker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A wolf that came back from somewhere high covered in blue feathers and contempt for the ground; it has seen the weather coming and will be elsewhere.', 'reviewed'),
  ('S2-28', 'Scalemane', 'set2A', 'montage_set2_A #S2-28', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A green slab that can''t decide if it''s a wolf or a wall and settled on both, immovably; bites with the conviction of something that used to be a predator.', 'reviewed'),
  ('S2-29', 'Greaveling', 'set2A', 'montage_set2_A #S2-29', 'organic', 'wild', 'T2', 'Gaia', NULL, 'tank', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A low, striped slab of bad temper and lower centre of gravity, built like a door that bites; pound for pound the most stubborn thing in the set.', 'reviewed'),
  ('S2-30', 'Snarlpelt', 'set2A', 'montage_set2_A #S2-30', 'organic', 'wild', 'T2', 'Chaos', NULL, 'nuker', NULL, 'mid', NULL, ARRAY['draft']::text[], 'A hyena-shaped problem that runs on spite and bad laughter, hackles up before it knows what''s annoyed it; the strategy is "yes, and harder."', 'reviewed'),
  ('S2-31', 'Scarmount', 'set2B', 'montage_set2_B #S2-31', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A wyrm that gave up flying and decided the ground was the only thing worth being; its hide is a quarry wall, and you will tire first.', 'reviewed'),
  ('S2-32', 'Bramblehowl', 'set2B', 'montage_set2_B #S2-32', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A wolf the size of a doorway that grew a hedge instead of a hide; it lets you come close, then becomes briefly all needle — a hug you regret.', 'reviewed'),
  ('S2-33', 'Bogmaster', 'set2B', 'montage_set2_B #S2-33', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A reptile shaped like a sunken log and marginally less excitable; it perfects being scenery until the precise moment it is teeth. Count the logs twice.', 'reviewed'),
  ('S2-34', 'Quillshroud', 'set2B', 'montage_set2_B #S2-34', 'organic', 'wild', 'T3', 'Thanatos', NULL, 'assassin', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A hunting-thing that wears its own death like a coat and lets a little fall on everyone it passes; the quills are the only warning, and they''re polite.', 'reviewed'),
  ('S2-35', 'Loamfist', 'set2B', 'montage_set2_B #S2-35', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A bear that ate a hillside and kept the personality; moss grows on its shoulders because it stands still long enough for moss to make plans.', 'reviewed'),
  ('S2-36', 'Skarn-Glide', 'set2B', 'montage_set2_B #S2-36', 'organic', 'wild', 'T3', 'Ouranos', NULL, 'striker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A flat slab of muscle and membrane that pours across the sky like a stingray; by the time you''ve looked up, the pass — and the argument — is over.', 'reviewed'),
  ('S2-37', 'Sloughback', 'set2B', 'montage_set2_B #S2-37', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A toad that grew until "leap" stopped being a verb it could afford; it occupies space like a dropped boulder, and is the safest place in any catastrophe.', 'reviewed'),
  ('S2-38', 'Greenmaw', 'set2B', 'montage_set2_B #S2-38', 'organic', 'wild', 'T3', 'Eros', NULL, 'support', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A drake that decided breathing fire was crude and breathing spring was funnier; where it exhales, cuts knit and bruises green over like fast-forward moss.', 'reviewed'),
  ('S2-39', 'Tuskmoot', 'set2B', 'montage_set2_B #S2-39', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A boar that grew antlers it didn''t ask for and a stubbornness it did; it plants itself across a path and becomes the path''s opinion on who passes.', 'reviewed'),
  ('S2-40', 'Nightreach', 'set2B', 'montage_set2_B #S2-40', 'organic', 'wild', 'T3', 'Thanatos', NULL, 'assassin', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A hunter built entirely out of reach, all elbow and patience; it picks the creature you thought was safe and proves "the corner" was a comforting story.', 'reviewed'),
  ('S2-41', 'Skyrender', 'set2B', 'montage_set2_B #S2-41', 'organic', 'wild', 'T3', 'Ouranos', NULL, 'striker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'The wyvern every villager means when they point at the sky and run; not the largest dragon, simply the fastest thing with claws you''ll meet this year.', 'reviewed'),
  ('S2-42', 'Stormherald', 'set2B', 'montage_set2_B #S2-42', 'organic', 'wild', 'T3', 'Ouranos', NULL, 'striker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A griffin that arrives a half-second ahead of its own thunder and enjoys the entrance; fly with it and your whole squad inherits its hurry.', 'reviewed'),
  ('S2-43', 'Duskrender', 'set2B', 'montage_set2_B #S2-43', 'organic', 'wild', 'T3', 'Ouranos', NULL, 'striker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'Skyrender''s quieter cousin, who learned the best time to be a fast thing with claws is when nobody can quite see the sky; it has been and gone twice.', 'reviewed'),
  ('S2-44', 'Warquill', 'set2B', 'montage_set2_B #S2-44', 'organic', 'wild', 'T3', 'Ouranos', NULL, 'striker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A griffin built less for grace than for arriving, fast, on top of whatever it disagreed with; it lands on the conversation, with the temper of an arrow.', 'reviewed'),
  ('S2-45', 'Glasswing-in-Summer', 'set2B', 'montage_set2_B #S2-45', 'organic', 'wild', 'T3', 'Eros', NULL, 'support', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A dragon the length of a fence rail and the weight of an idea, with four wings like stained-glass leaves; it hangs over a fight just sounding nice.', 'reviewed'),
  ('S2-46', 'Lawbright', 'set2B', 'montage_set2_B #S2-46', 'organic', 'wild', 'T3', 'Cosmos', NULL, 'control', NULL, 'apex', NULL, ARRAY['draft']::text[], 'The griffin that decided its cousins were undignified and went into administration; it does not strike, it rules, drawing lines the battle must respect.', 'reviewed'),
  ('S2-47', 'Mosscloak', 'set2B', 'montage_set2_B #S2-47', 'organic', 'wild', 'T3', 'Eros', NULL, 'support', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A wyvern so overgrown it looks landscaped, every scale furred with moss; it wraps a wing over your worst-broken ally and waits out the wound.', 'reviewed'),
  ('S2-48', 'Sunder-the-Gale', 'set2B', 'montage_set2_B #S2-48', 'organic', 'wild', 'T3', 'Ouranos', NULL, 'striker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'The wyvern that took the family talent for speed and went professional; it crosses the whole sky between heartbeats, leaves gold and a wound, gone.', 'reviewed'),
  ('S2-49', 'Gravewing', 'set2B', 'montage_set2_B #S2-49', 'organic', 'wild', 'T3', 'Thanatos', NULL, 'assassin', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A demon built like an empty coat with teeth, all leather and hunger; it rides the high dark and drops on your weakest like a settled debt.', 'reviewed'),
  ('S2-50', 'Greywyrm', 'set2B', 'montage_set2_B #S2-50', 'organic', 'wild', 'T3', 'Cosmos', NULL, 'control', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A dragon that turned slowly to grey ordered stone and preferred the arrangement; it rules a fight like a law rules a town — invisibly, then completely.', 'reviewed'),
  ('S2-51', 'Cinderhowl', 'set2B', 'montage_set2_B #S2-51', 'organic', 'wild', 'T3', 'Chaos', NULL, 'nuker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A wolf that runs too hot to touch and far too hot to reason with; it does not attack so much as combust at you, gloriously and expensively.', 'reviewed'),
  ('S2-52', 'Drownjaw', 'set2B', 'montage_set2_B #S2-52', 'organic', 'wild', 'T3', 'Thanatos', NULL, 'assassin', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A predator the colour of deep cold water, built around a jaw that closes once and means it; it takes one creature and waits out the struggle.', 'reviewed'),
  ('S2-53', 'Hoarfast the Patient', 'set2B', 'montage_set2_B #S2-53', 'organic', 'wild', 'T3', 'Cosmos', NULL, 'control', NULL, 'apex', NULL, ARRAY['draft']::text[], 'An ice dragon that concluded heat was a passing fashion; it rules a fight by lowering it — the room, the morale, the enemy''s reaction time.', 'reviewed'),
  ('S2-54', 'The Manyfold', 'set2B', 'montage_set2_B #S2-54', 'organic', 'wild', 'T3', 'Thanatos', NULL, 'assassin', NULL, 'apex', NULL, ARRAY['draft']::text[], 'Something fused that should have stayed two things, then kept agreeing until it was several; too many legs, too many eyes, too many directions to block.', 'reviewed'),
  ('S2-55', 'Hivewrath', 'set2B', 'montage_set2_B #S2-55', 'organic', 'wild', 'T3', 'Chaos', NULL, 'nuker', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A wasp the size of a war-dragon and roughly that calm about being looked at; it attacks like an overturned hive — all at once, from everywhere.', 'reviewed'),
  ('S2-56', 'Cairngorge', 'set2B', 'montage_set2_B #S2-56', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A brute gone so far toward terrain that moss settled on its back and stones learned its shape; it plants in front of the squad and becomes a wall with tusks.', 'reviewed'),
  ('S2-57', 'Mosshart', 'set2B', 'montage_set2_B #S2-57', 'organic', 'wild', 'T3', 'Eros', NULL, 'support', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A stag whose antlers are a small slow forest and whose patience is the same; where it stands, the squad''s wounds green over and sprout something absurd.', 'reviewed'),
  ('S2-58', 'Hallowmane', 'set2B', 'montage_set2_B #S2-58', 'organic', 'wild', 'T3', 'Cosmos', NULL, 'control', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A great horned hound so composed it seems to know how the fight ends; its pale mane throws a lawful light in which surprises simply don''t happen.', 'reviewed'),
  ('S2-59', 'Plateback', 'set2B', 'montage_set2_B #S2-59', 'organic', 'wild', 'T3', 'Gaia', NULL, 'tank', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A beast that solved being hit by becoming a closed box with legs; nothing about it is fast or sharp, everything about it is in the way.', 'reviewed'),
  ('S2-60', 'The Long Mourning', 'set2B', 'montage_set2_B #S2-60', 'organic', 'wild', 'T3', 'Thanatos', NULL, 'assassin', NULL, 'apex', NULL, ARRAY['draft']::text[], 'A serpent made of the colour grief goes when left alone too long; it does not bite and flee — it winds, and what it wraps simply gets quieter.', 'reviewed'),
  ('batch3-001', 'Vorraxiel, the Unmade Crown', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_56 AM (1).png', 'organic', 'god', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A demon-lord who rules by subtraction, retiring kingdoms wholesale and keeping a tally of the unmade; even its weeping fire finds the work depressing.', 'reviewed'),
  ('batch3-002', 'Pyrendax, the Open Furnace', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_56 AM (2).png', 'organic', 'god', NULL, 'Chaos', NULL, 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'One enormous opinion about fire with no punctuation and no defenses, because it never plans to be hit twice — by then it''s already over.', 'reviewed'),
  ('batch3-003', 'Sylvanthus, the Weeping Bloom', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_56 AM (3).png', 'organic', 'god', NULL, 'Eros', 'Thanatos', 'support', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A god half garden, half graveyard, nursing allies and rotting foes from one root; the flowers it leaves on your corpse are sincere, and hungry.', 'reviewed'),
  ('batch3-004', 'Nyxaeril, the Drifting Shroud', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_56 AM (4).png', 'organic', 'god', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A violet lady who moves like bad news — quietly, then already here; politely lets you finish your sentence before ending the rest of them.', 'reviewed'),
  ('batch3-005', 'Tharragost, the Iron Magistrate', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_57 AM (5).png', 'organic', 'god', NULL, 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A mountain of stone and gold whose ruling on every matter is "no"; it has stood in one argument for an age and considers itself winning.', 'reviewed'),
  ('batch3-006', 'Veshrali, the Honeyed Swarm', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_57 AM (6).png', 'organic', 'god', NULL, 'Chaos', 'Eros', 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A swarm-lord that beat mortality by being a population, beautiful up close and cheerful about it; loves its children fiercely and spends them instantly.', 'reviewed'),
  ('batch3-007', 'Hieloquen, the Verdict of Frost', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_57 AM (7).png', 'organic', 'god', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A frost-lord who decides ahead of time exactly how slowly your turn arrives; the quickest of its court, using speed only to make everyone else late.', 'reviewed'),
  ('batch3-008', 'Grimbathok, the Roost of Endings', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_57 AM (8).png', 'organic', 'god', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A winged thing that perches like a held breath and hunts only the finishable, with an unerring eye for which of you that is today.', 'reviewed'),
  ('batch3-009', 'Maelyrra, the Gentle Current', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_57 AM (9).png', 'organic', 'god', NULL, 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A river-serpent whose kindness arrives faster than your enemies'' cruelty; the swiftest healer in the pantheon, spending all that speed on being kind sooner.', 'reviewed'),
  ('batch3-010', 'Skarnathoth, the Bristled Verdict', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_10_58 AM (10).png', 'organic', 'god', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'The court''s hound, the size of a grievance and twice as committed; sent to end a thing loudly, in front of witnesses, so the witnesses learn.', 'reviewed'),
  ('batch3-011', 'Malzevorrin, the Scarlet Adjudicator', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_00 AM (1).png', 'organic', 'god', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A magistrate of harm who thinks everything living is mid-trial and mostly guilty; never lost a case, since it writes the law, verdict, and obituary.', 'reviewed'),
  ('batch3-012', 'Ashvargod, the Ordered Grave', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_01 AM (2).png', 'organic', 'god', NULL, 'Thanatos', 'Cosmos', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'An armored lord who files every killing in triplicate and seals it with a crown; not a blade but a writ — slower, colder, impossible to appeal.', 'reviewed'),
  ('batch3-013', 'Quorruveth, the Reaching Hollow', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_01 AM (3).png', 'organic', 'god', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A lord shaped like a hunger that grew too many ways to reach, never the same silhouette twice; it has more arms than you have plans.', 'reviewed'),
  ('batch3-014', 'Yssraketh, the Antlered Lament', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_01 AM (4).png', 'organic', 'god', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A lady whose every emotion arrives as an explosion; her antlers catch other people''s last moments, and she mourns each kill loudly and insincerely.', 'reviewed'),
  ('batch3-015', 'Sceptraël, the Glass Wing', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_01 AM (5).png', 'organic', 'god', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A dragon of blue glass and colder logic that breathes not fire but terms and conditions, binding; where it banks, the light apologizes for being late.', 'reviewed'),
  ('batch3-016', 'Cryselthorn, the Pale Flame Warden', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_02 AM (6).png', 'organic', 'god', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A warden whose order-colored flame doesn''t destroy but files you under "later," which in a fast fight is the same as never; its blue fire seals shut.', 'reviewed'),
  ('batch3-017', 'Heartholt, the Verdant Bastion', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_02 AM (7).png', 'organic', 'god', NULL, 'Eros', 'Gaia', 'support', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A serpent-lord so overgrown it became geography — a fortress that gardens, the steadiest god in a court of strange ones, healing an army behind its bulk.', 'reviewed'),
  ('batch3-018', 'Ignavarro, the Laughing Pyre', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_02 AM (8).png', 'organic', 'god', NULL, 'Chaos', 'Ouranos', 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'An arsonist with wings and a sense of humour about gravity; it strikes first because it''s bored by the part of fights where the enemy participates.', 'reviewed'),
  ('batch3-019', 'Lethemora, the Tender Rot', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_02 AM (9).png', 'organic', 'god', NULL, 'Thanatos', 'Eros', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A horror that kills the way some people hug — too long, too hard, past when you asked it to stop; it will miss you terribly, starting now.', 'reviewed'),
  ('batch3-020', 'Mulgaroth, the Buried King', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_14_03 AM (10).png', 'organic', 'god', NULL, 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A king who was buried, disagreed, and came back wearing the hill; the heaviest thing in the pantheon, ruling by being permanently in everything''s way.', 'reviewed'),
  ('batch3-021', 'Belzaroth, the Crowned Ember', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_08 AM (1).png', 'organic', 'god', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'The portrait the word "demon-lord" paints before it knows better — horned, winged, crowned; old enough to have started the cliché, vain enough to keep it.', 'reviewed'),
  ('batch3-022', 'Thronabael, the Sole Bane', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_09 AM (2).png', 'organic', 'god', NULL, 'Thanatos', NULL, 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A serpent-lord refined down to a single verb — end. No defense, no flourish, only the one cut, perfected across an embarrassing number of eras.', 'reviewed'),
  ('batch3-023', 'Mossgrave, the Slow Mercy', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_09 AM (3).png', 'organic', 'god', NULL, 'Eros', 'Gaia', 'support', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A moss-mounded titan that heals like a forest recovering from fire — slowly, completely, on its own schedule; it considers most emergencies mere impatience.', 'reviewed'),
  ('batch3-024', 'Zephlarael, the Silver Verdict', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_09 AM (4).png', 'organic', 'god', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A dragon sanded down to pure velocity wrapped in just enough order to survive it; the quickest thing alive, spending all that speed to simply go first.', 'reviewed'),
  ('batch3-025', 'Skritthalax, the Mandible Choir', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_09 AM (5).png', 'organic', 'god', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A lord technically singular and morally a swarm, hungry in one direction; it doesn''t roar — it chitters, the sound of the fight''s maths turning against you.', 'reviewed'),
  ('batch3-026', 'Aurelvane, the Antlered Decree', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_10 AM (6).png', 'organic', 'god', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A stag-shouldered lord of armoured blue carrying the court''s law in its antlers; the most regal and least hurried, because order properly enforced never rushes.', 'reviewed'),
  ('batch3-027', 'Mordravspine, the Coiled Sepulchre', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_10 AM (7).png', 'organic', 'god', NULL, 'Thanatos', 'Gaia', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A serpent-lord built like a hill that decided to hunt; it kills thoroughly, not quickly, the one assassin you cannot outlast — it brought the longer afternoon.', 'reviewed'),
  ('batch3-028', 'Cindraxis, the Forge-Heart', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_10 AM (8).png', 'organic', 'god', NULL, 'Chaos', 'Ouranos', 'nuker', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A draconic furnace-lord whose chest is a small sun on a short fuse, perpetually about to make that everyone''s problem; closer to weather than animal.', 'reviewed'),
  ('batch3-029', 'Brumavex, the Glacial Sentence', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_10 AM (9).png', 'organic', 'god', NULL, 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'A frost-lord built like a moving glacier — barely moving, impossible to argue with; given time, ice wins every standoff, and it has all the time.', 'reviewed'),
  ('batch3-030', 'Vaelgrith, the Sundering Reach', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_16_11 AM (10).png', 'organic', 'god', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['demon-lord', 'boss']::text[], 'An elder of reaching things — a limb that forgot it ever needed a body, governing the tentacled Hollow-Court by being the longest thing in any room.', 'reviewed'),
  ('batch3-031', 'Cogwright Mk.I "Sentinel"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_34 AM (1).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'The foundry''s first, most honest model: a riveted bronze sentinel whose whole personality is "hold this line," running on wound springs and one repeating thought.', 'reviewed'),
  ('batch3-032', 'Cogwright Mk.II "Pincer"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_34 AM (2).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A foundry crab machined for one verb. Its shell takes hits like a safe takes burglars; it scuttles to whatever it was told to hold, then holds it forever.', 'reviewed'),
  ('batch3-033', 'Cogwright Mk.III "Watchman"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_35 AM (3).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A one-eyed brass watchman on spindly legs, built to stare at one problem until it stops being one. It never blinks, and finds your attempts to leave its gaze faintly insulting.', 'reviewed'),
  ('batch3-034', 'Cogwright Mk.IV "Boilerback"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_35 AM (4).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A barrel-chested model with a boiler for a torso and the disposition of a closed door. It guards by being too solid to get past, and likes its pressure rating.', 'reviewed'),
  ('batch3-035', 'Cogwright Mk.V "Deepdiver"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_35 AM (5).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A sealed foundry diver rated for crushing depths, repurposed to stand in the way on dry land. It moves as if wading deep water, because its gears insist it still is.', 'reviewed'),
  ('batch3-036', 'Cogwright Mk.VI "Leapwork"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_35 AM (6).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A pale clockwork hare, light in shell and heavy in spring, built to fling itself between an ally and a bad idea. The closest the foundry came to endearing — at a quarter-ton.', 'reviewed'),
  ('batch3-037', 'Cogwright Mk.VII "Skitterframe"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_36 AM (10).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A low brass crawler on too many legs that lays a grid of cabling and decides who''s allowed to hurry. It ticks toward you with no malice, no mercy, and excellent traction.', 'reviewed'),
  ('batch3-038', 'Cogwright Mk.VIII "Owlwork"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_36 AM (7).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A brass owl whose head turns past comfort and whose lens-eyes tally you against a standard you can''t see. The foundry''s auditor: it doesn''t hoot, it *ticks* — somehow worse at 3am.', 'reviewed'),
  ('batch3-039', 'Cogwright Mk.IX "Tidewright"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_36 AM (8).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'A teal-glass dome on brass armatures, drifting on gyros and projecting a field it would prefer you respect. The strangest model the foundry signed off on; nobody''s sure how it floats.', 'reviewed'),
  ('batch3-040', 'Cogwright Mk.X "Bastion-Shell"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_18_36 AM (9).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'clockwork']::text[], 'The capstone: a bronze tortoise-shell on treads, built to roll into position once and become permanent. When it locks down, it stops being a creature and starts being terrain.', 'reviewed'),
  ('batch3-041', 'Branchflayer', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_08 AM (1).png', 'organic', 'legendary', NULL, 'Thanatos', 'Eros', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'Someone grafted grief onto a growing thing and it said yes; now it reaches into wherever you used to be, mistaking you for soil.', 'reviewed'),
  ('batch3-042', 'Vespermoth', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_08 AM (2).png', 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'It came to the lamp, kept coming, became the lamp''s idea of a face; its almost-meaningful wings make you follow one fatal step.', 'reviewed'),
  ('batch3-043', 'Gallowsthread', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_08 AM (3).png', 'organic', 'legendary', NULL, 'Thanatos', NULL, 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'Hung once and decided not to stop, it sways in the air full of one enormous intention, doing a single thing to you very thoroughly.', 'reviewed'),
  ('batch3-044', 'Lampveil', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_08 AM (4).png', 'organic', 'legendary', NULL, 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'Beautiful from a survivable distance, it drifts trailing glowing kindnesses, mending your wounds the way a tide loves the shore: completely, unasked.', 'reviewed'),
  ('batch3-045', 'Orantmantis', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_09 AM (5).png', 'organic', 'legendary', NULL, 'Eros', 'Chaos', 'support', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'It prays without pause to no god, all those folded hands, and the unsettling part is the prayer works — nobody knows what it wants.', 'reviewed'),
  ('batch3-046', 'Thornmitre', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_09 AM (6).png', 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'A priest of something that stopped writing back, it still takes confession, and rather more; it absolves you of everything you had left.', 'reviewed'),
  ('batch3-047', 'Palewretch', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_09 AM (7).png', 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'Too tall, too thin, too fast for either, it crosses a room before you decide to leave; it does not run, it arrives like bad news.', 'reviewed'),
  ('batch3-048', 'Maulbrood', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_09 AM (8).png', 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'A fusion that couldn''t agree how many mouths to have, so it took all of them; it does not strategise, it converges, loudly, from everywhere.', 'reviewed'),
  ('batch3-049', 'Rootmurk', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_09 AM (9).png', 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'A blight that grew downward and forgot to stop being hungry; it has already arrived underneath, and your roots were its several turns ago.', 'reviewed'),
  ('batch3-050', 'Sinewchant', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_24_10 AM (10).png', 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'abomination']::text[], 'It lost its skin and has been upset ever since in a key only it can hold; the flaying just freed the screaming, and each kill makes it worse.', 'reviewed'),
  ('batch3-051', 'Stormcrag', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_26 AM (1).png', 'organic', 'legendary', NULL, 'Gaia', 'Ouranos', 'tank', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A walking ridgeline that learned to hurry and resents being asked; storms gather on its spines, and when it moves the horizon revises itself.', 'reviewed'),
  ('batch3-052', 'Brinemaw', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_26 AM (2).png', 'organic', 'legendary', NULL, 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'Something the deep grew when it tired of being calm; it carries the sea''s worst mood, and the tail arrives a second after you thought you dodged.', 'reviewed'),
  ('batch3-053', 'Cairnsaur', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_26 AM (3).png', 'organic', 'legendary', NULL, 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'Built like a collapsed monument and as eager to move; things that die near it stay, becoming the cairn it carries without comment or burden.', 'reviewed'),
  ('batch3-054', 'Galewyrm', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_26 AM (4).png', 'organic', 'legendary', NULL, 'Ouranos', 'Chaos', 'striker', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A dragon that treats altitude as a weapon and gravity as a bullied ally; it fights from above, briefly, on the way down — your only warning.', 'reviewed'),
  ('batch3-055', 'Hollowtithe', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_27 AM (5).png', 'organic', 'legendary', NULL, 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A mountain of an animal always emptier than its size suggests; it collects what it kills not to eat but to fill, and has never once felt full.', 'reviewed'),
  ('batch3-056', 'Bastion-Mk.I "Aegistread"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_27 AM (6).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'The first thing the foundry got right and never improved on. It doesn''t advance, retreat, or have opinions — it *holds*. Built, not born; the only thing it fears is rust.', 'reviewed'),
  ('batch3-057', 'Bastion-Mk.II "Striplance"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_27 AM (7).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'The model after the foundry got bored of pure defense and added a lance — for keeping things *out*, not getting them. Cleaner-lined than its sibling, and twice as smug.', 'reviewed'),
  ('batch3-058', 'Bastion-Mk.III "Rivetwall"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_27 AM (8).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'A bunker that learned to walk, then sensibly chose not to. Every rivet argues against a way through; it eats the blows meant for softer creatures, unable to conceive of damage.', 'reviewed'),
  ('batch3-059', 'Bastion-Mk.IV "Grudgeworks"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_27 AM (9).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'The chassis built after someone hit the Mk.III and got away with it. Soot-black and patient, it doesn''t forgive a blow — it *files* it, then refunds the whole account at once.', 'reviewed'),
  ('batch3-060', 'Bastion-Mk.V "Longbarrel"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_27_28 AM (10).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'The model where the foundry admitted it had built a turret with legs. It still won''t move much, but now that''s a firing decision — it holds ground by making the ground lethal.', 'reviewed'),
  ('batch3-061', 'Quarryking', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_44 AM (1).png', 'organic', 'legendary', NULL, 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A walking quarry that crystallised its own bad temper and sheds it as shrapnel; it rules nothing — it just will not get out of the way.', 'reviewed'),
  ('batch3-062', 'Worldspine', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_44 AM (2).png', 'organic', 'legendary', NULL, 'Gaia', NULL, 'tank', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'The biggest single thing in the clade, geology with a pulse; it does not attack or hurry, it is simply there, a horizon standing in your way.', 'reviewed'),
  ('batch3-063', 'Voltdrake', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_45 AM (3).png', 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A dragon wired like a coming storm and just as orderly; the glow in its chest is not a heart but a schedule, and it strikes on the beat.', 'reviewed'),
  ('batch3-064', 'Tidalmaw', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_45 AM (4).png', 'organic', 'legendary', NULL, 'Ouranos', 'Gaia', 'striker', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A dragon-beast built like a wave with legs, fast as surf and heavy as the water under it; it does not chase the slow — it catches everyone.', 'reviewed'),
  ('batch3-065', 'Sporedrake', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_45 AM (5).png', 'organic', 'legendary', NULL, 'Ouranos', 'Chaos', 'striker', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A dragon assembled in a hurry by something out of patience; faster than it should be, wildly inaccurate, brilliant or comedy turn by turn.', 'reviewed'),
  ('batch3-066', 'Ironcrag', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_46 AM (6).png', 'organic', 'legendary', NULL, 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['kaiju', 'apex']::text[], 'A kaiju whose hide grew in such tidy plates people swear it''s a construct; entirely organic, entirely armored, walling calmly and resentfully.', 'reviewed'),
  ('batch3-067', 'Vanguard-Mk.I "Skylance"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_46 AM (7).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'The foundry''s attempt at a flying mech, which produced a mech that hovers menacingly and insists it could. The thruster-vanes are real; the flight is a firmly-held intention.', 'reviewed'),
  ('batch3-068', 'Vanguard-Mk.II "Deepkeel"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_46 AM (8).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'They took the flight model, dropped the pretension, and added enough hull to sink a harbour. It plants like a ship run aground and dares the tide to move it. It won''t.', 'reviewed'),
  ('batch3-069', 'Vanguard-Mk.III "Pikeward"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_46 AM (9).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'A construct issued a spear and one instruction — *nothing gets past* — and the literal devotion of a thing that can''t interpret it otherwise. Within reach of the pike, battles end.', 'reviewed'),
  ('batch3-070', 'Vanguard-Mk.IV "Boilerhulk"', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_29_47 AM (10).png', 'construct', 'wild', 'T3', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['construct', 'mecha']::text[], 'The chassis that runs on actual fire, which newer models call quaint and which outlasts them all. Obsolete, leaking heat from every seam, still bolted to the fort''s most important door.', 'reviewed'),
  ('batch3-071', 'Sigilram', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_32_19 AM (1).png', 'organic', 'wild', 'T2', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['beast']::text[], 'A heavy-coated beast whose fleece grew faint orderly markings that hold the air quieter. Not a fighter but a *settler*: disputes lose heat near it, dice land flatter, tempers cool.', 'reviewed'),
  ('batch3-072', 'Nyxhydra', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_32_19 AM (2).png', 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'A night-coloured hydra that treats decapitation as a scheduling problem; it strikes in draining waves, an argument you keep almost winning.', 'reviewed'),
  ('batch3-073', 'Taurok, the Labyrinth-Keeper', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_32_19 AM (3).png', 'organic', 'legendary', NULL, 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['greek-myth', 'champion']::text[], 'The bull at the heart of the maze that never needed it — built to keep you in; a straight charge is the only prayer he still remembers.', 'reviewed'),
  ('batch3-074', 'Keruthos, the Threshold Hound', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_32_20 AM (4).png', 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['greek-myth', 'champion']::text[], 'The hound at the gate no one leaves, three heads so nothing slips past while one sleeps; it does not hate the dead, it files them.', 'reviewed'),
  ('batch3-075', 'Aellopis, the Snatching Gale', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_32_20 AM (5).png', 'organic', 'legendary', NULL, 'Ouranos', 'Thanatos', 'striker', NULL, NULL, NULL, ARRAY['greek-myth', 'champion']::text[], 'The storm-wind that learned to steal, given a face, a grudge, and talons; she does not linger to fight, she passes, and your blessing is gone.', 'reviewed'),
  ('batch3-076', 'Stheneira, the Stone-Gaze', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_32_20 AM (6).png', 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['greek-myth', 'champion']::text[], 'Punished for another''s crime, turning messengers to stone ever since; the snakes are honest, the face ruins you — she is not cruel, just tired.', 'reviewed'),
  ('batch3-077', 'Khalkeon, the Unkillable Mane', 'batch3', 'art/batch3/Mutant Images 3/ChatGPT Image Jun 26, 2026, 12_32_20 AM (7).png', 'organic', 'legendary', NULL, 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['greek-myth', 'champion']::text[], 'The lion whose pelt turned every weapon ever raised — a marvellous, lonely gift; it guards now the way it once could not be guarded against.', 'reviewed'),
  ('batch4-001', 'Aurelet', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A fox-kit lit from inside like a held candle, and about as fond of being held. It heals because it can''t help it — proximity makes wounds embarrassed enough to close.', 'reviewed'),
  ('batch4-002', 'Lumbkin', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A lamb so radiant wolves report a moral crisis before eating one anyway. It follows kind people home and gentle ones to their graves, where it stands vigil and glows.', 'reviewed'),
  ('batch4-003', 'Halofleece', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A wool-cloud with hooves and a halo it''s too young to have earned, which never stops it. It throws itself between danger and anyone smaller — courage made comic by its footstool size.', 'reviewed'),
  ('batch4-004', 'Sunnix', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A fox-kit that wakes at dawn and *becomes* dawn, to the annoyance of late sleepers. Its exhausting hope reads as a stat buff — the only context optimism ever won an argument.', 'reviewed'),
  ('batch4-005', 'Peeplume', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A chick of pure morning peeping the three notes that switched the first sunrise on. One is cute; a choir is a healing engine and a liability, because nothing nearby gets to sleep.', 'reviewed'),
  ('batch4-006', 'Glimmerfae', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A palm-sized thing of light and good intentions that mends what it lands on — including the occasional open wound it was curious about. Healers adore it; surgeons ask it to wait outside.', 'reviewed'),
  ('batch4-007', 'Reliquell', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A tortoise whose shell grew a tiny shrine instead of barnacles. Step inside its glow and the world''s edges round off. It moves at the speed of devotion: you arrive, eventually.', 'reviewed'),
  ('batch4-008', 'Dawnling', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A fawn that walks like the first minute of a morning you didn''t deserve; grass un-wilts where it steps, and it makes the fighters around it harder to discourage.', 'reviewed'),
  ('batch4-009', 'Vesperwing', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A small winged guardian that works best at the hour the light gives up, folding luminous wings over the dying; they die less afraid, which it counts as a win.', 'reviewed'),
  ('batch4-010', 'Gloriate', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A river-otter in late-afternoon gold, ferrying blessings from somewhere upstream nobody''s found. It scrubs curses off you the brisk way a mother does, and is just as immune to complaint.', 'reviewed'),
  ('batch4-011', 'Gildehart', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A young stag with the first hint of wings and the full confidence of an older one, setting a perimeter of decorum and enforcing it on incoming violence.', 'reviewed'),
  ('batch4-012', 'Solram', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A young ram whose horns ring like a temple bell at noon, scattering the small despairs that gather in shade. It headbutts predators to *correct*, not wound; a few don''t leave at all.', 'reviewed'),
  ('batch4-013', 'Sanctback', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A tortoise grown into a moving chapel, taking the duty very seriously and very slowly. Pilgrims sleep under its shell down dangerous roads and wake alive — which there is the whole review.', 'reviewed'),
  ('batch4-014', 'Empyrling', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A deer given wings by something that believed in it more than was strictly safe. It glides the battlefield distributing healing like alms, untroubled by arrows it really ought to mind.', 'reviewed'),
  ('batch4-015', 'Seraphlet', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A small thing with too many wings and the calm of something that read the ending and found it acceptable; it heals in a warm wave while watching you, unnervingly.', 'reviewed'),
  ('batch4-016', 'Sunscale', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A hatchling dragon of pure daylight that hasn''t learned dragons should be terrifying. It curls around what it loves and glows — a serviceable shield, a space heater, and twice a wolf-eater.', 'reviewed'),
  ('batch4-017', 'Owlgilt', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'An owl the dawn reached before the night could, leaving it gold-eyed and incurably reassuring. It hoots only to say the thing in the dark is handled; travellers sleep better than they''ve earned.', 'reviewed'),
  ('batch4-018', 'Aurivex', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A winged fox delivering benedictions at a full, undignified sprint — too restless to be properly worshipped. In a fight it laps the party endlessly, stitching everyone back a half-step at a time.', 'reviewed'),
  ('batch4-019', 'Goldcalf', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A gold creature so beautiful whole villages once worshipped it instead of feeding their fields. It finds this a bit much, but keeps healing whoever falls down — which only encourages cults.', 'reviewed'),
  ('batch4-020', 'Hallowdeer', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A stag that consecrates dirt simply by standing on it: wonderful to fight beside, inconvenient to relocate. It won''t leave hallowed ground on principle, even when leaving would be wiser.', 'reviewed'),
  ('batch4-021', 'Glorehart', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'The full flower of the radiant deer — a stag crowned in sunrise, bearing of something that declined godhood twice. It heals the field with a largesse that shames lesser predators into bowing.', 'reviewed'),
  ('batch4-022', 'Sunsovren', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A ram grown into a small sun with a temper and a clear sense of jurisdiction, ending wars by standing in the middle and glowing until both sides reconsider.', 'reviewed'),
  ('batch4-023', 'Reliquarch', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'The grandparent of the radiant tortoises, a walking cathedral that walks roughly never. Stand inside its sanctuary and you''re briefly un-killable and extremely behind schedule. It won''t apologise.', 'reviewed'),
  ('batch4-024', 'Glorywing', 'batch4', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant', 'holy']::text[], 'A winged stag that takes flight like a hymn reaching its last note, carrying no rider — only everyone''s spirits, upward, right as they were about to give up.', 'reviewed'),
  ('batch4-025', 'Sablewidow', 'batch4', NULL, 'organic', 'wild', 'T2', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'After two dozen creatures made of sunrise, here is the bill: a winged shadow with a widow''s patience that folds dark over the dying and quietly drinks the difference.', 'reviewed'),
  ('batch4-026', 'Crystgrief', 'batch4', NULL, 'organic', 'wild', 'T2', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A beast that wept so long its tears went hard and grew back inward as amethyst spines. Each shard is an unfinished sorrow, shared generously, point-first. No fortune is worth the harvest.', 'reviewed'),
  ('batch4-027', 'Frostwraith', 'batch4', NULL, 'organic', 'wild', 'T2', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A shadow-thing that learned cold from the dead and wields it like a grudge; its breath is the chill of a room something just left, and it hunts the warm.', 'reviewed'),
  ('batch4-028', 'Tatterhowl', 'batch4', NULL, 'organic', 'wild', 'T2', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A starved silhouette draped in the funeral-rags of everything it''s caught, rattling them as it runs to advertise the back-catalogue. It fights with the frenzy of a thing that lost everything ages ago.', 'reviewed'),
  ('batch4-029', 'Falseangel', 'batch4', NULL, 'organic', 'wild', 'T2', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A pale, fae-winged thing that looks like it wandered in from the radiant block, which is exactly the trap: it mimics the light to get near the trusting, then collects.', 'reviewed'),
  ('batch4-030', 'Scarletwidow', 'batch4', NULL, 'organic', 'wild', 'T2', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'The senior of the dark interlude, a wyrm-shaped shadow stitched in arterial red that takes a tithe from everything it touches and calls the arrangement scripture.', 'reviewed'),
  ('batch4-031', 'Sleetkit', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A fox spun out of breath on a winter morning, friendliest and quickest of the frost court — used mostly for mischief, occasionally for murder if you didn''t share.', 'reviewed'),
  ('batch4-032', 'Snowdown', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A snow-hare so soft it looks like an apology and so fast it kicks powder in three faces before you finish saying "aww" — harmless right up until it very much isn''t.', 'reviewed'),
  ('batch4-033', 'Mistlurk', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A river-otter that forgot to stay solid and now commutes by fog — seen on the far bank and felt at your ankle in one breath. It drowns people the way fog does.', 'reviewed'),
  ('batch4-034', 'Wispcalf', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A drifting baby-sprite that looks like it''s daydreaming until it crosses the room in a single twitch — too dreamy to seem dangerous, which is the dream''s whole job.', 'reviewed'),
  ('batch4-035', 'Frostpaw', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A prim, faintly judgmental frost-fox that turns every surface it crosses into ice for the next person, calls it a public service, and watches you slip like someone who warned you.', 'reviewed'),
  ('batch4-036', 'Galewolf', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'The first of the storm-wolves, darker and colder than the kits, running at the speed of the wind that pushes a blizzard ahead of it. It doesn''t play; it hunts like weather.', 'reviewed'),
  ('batch4-037', 'Hoarstag', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A stag of midwinter dusk whose antlers wear hoarfrost like a sharper second crown, moving with the gliding speed of a cold front and its indifference, freezing the air behind it.', 'reviewed'),
  ('batch4-038', 'Stormveil', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A storm-wolf that travels inside its own bad weather, a smear of cold vapor that picks its moment from behind the curtain. Half the time you''re swinging at the squall, not the wolf.', 'reviewed'),
  ('batch4-039', 'Tempestmane', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'The grandest storm-wolf, mane piled into its own thunderhead and a temper to match: it starts a fight quick and *accelerates*, which is deeply unfair from an already-fast predator.', 'reviewed'),
  ('batch4-040', 'Sleetsprite', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A darker, sleeker Wispcalf cousin carrying a little frozen star on its tail like a slingshot, lurking in deep cold water to lob hail at things that lean too far over the surface.', 'reviewed'),
  ('batch4-041', 'Floedrift', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A frost-seal pup that, against all visual evidence, is one of the court''s fastest — a barrel of blubber that moves like a skipped stone and bonks intruders, not understanding it''s a weapon.', 'reviewed'),
  ('batch4-042', 'Glaciback', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A turtle that solved being slow by growing an ice-shell: a paperweight on land, on ice a low blue blur that knocks the legs from things its size.', 'reviewed'),
  ('batch4-043', 'Brumotter', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'The Mistlurk''s solid, cheekier relative — twice as smug and just as quick — riding its own cold currents to surface, hit, and duck before the reply lands. It keeps the shiny things.', 'reviewed'),
  ('batch4-044', 'Frostling', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'The brightest, most overconfident ice-sprite, a thumb-sized thing convinced it''s a dragon and behaving so. It nips much larger creatures and zips away vibrating with pride; the ones that miss learn cold respect.', 'reviewed'),
  ('batch4-045', 'Cryowulf', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'A frost-wolf that grew its blizzard *inward* into a mane of literal ice-blades — less weather, more weapon. Its wounds take a strange long time to warm back up.', 'reviewed'),
  ('batch4-046', 'Frostfury', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'The frost court with the gloves off — a snarling knot of crest, fin and bad weather that hits like the worst ten seconds of a storm and, unlike its cousins, fully commits.', 'reviewed'),
  ('batch4-047', 'Wintreon', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'The aerodynamic specialist of the frost-wolves, all swept lines and silence, built to arrive before its own sound — the quietest fast thing in the cold, a contradiction resolved at your expense.', 'reviewed'),
  ('batch4-048', 'Verglashart', 'batch4', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost', 'sky']::text[], 'The grandest frost-deer, antlers grown clear as black ice and twice as treacherous, moving like the first hard freeze — beautiful, total, impossible to walk on safely.', 'reviewed'),
  ('batch4-049', 'Skysovereign', 'batch4', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'The volume''s first true apex: a feathered-light dragon faster than weather that judges from above, owns all the altitude, and shares none.', 'reviewed'),
  ('batch4-050', 'Azuredrake', 'batch4', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'Skysovereign''s darker, swifter twin — a storm-riding serpent that doesn''t fly so much as cut, arriving twice and gone before the thunder explains it.', 'reviewed'),
  ('batch4-051', 'Cinderwyrm Patriarch', 'batch4', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'The Flight''s oldest molten apex: a quarry-fire dragon that does not breathe flame but passes sentence, and the verdict is always ash.', 'reviewed'),
  ('batch4-052', 'Slagmaw Tyrant', 'batch4', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'Rules its cooling lava-field and taxes every trespasser in the currency of being on fire; the foundry throat is your only warning, and it''s not enough.', 'reviewed'),
  ('batch4-053', 'Emberscourge', 'batch4', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'The Flight''s working arsonist, lean and tireless and faintly bored, burning things less from fury than a sense they ought to be ash by now.', 'reviewed'),
  ('batch4-054', 'Furnace-Crowned Wyrm', 'batch4', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'A vain apex that mistook its rack of door-sized burning horns for a crown, and you for a subject who hasn''t yet bowed; carrion birds know dusk is dinner.', 'reviewed'),
  ('batch4-055', 'Ashen Doom-Drake', 'batch4', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'The Flight''s pessimist, proven right too often, raining slow burning cinders on places having a nice century; it is not in a hurry, doom rarely is.', 'reviewed'),
  ('batch4-056', 'Riptide Wyrm', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'Deep-water serpent lit by cold cyan that never offered warmth; it does not maul but passes through, and afterward someone is simply gone from the line.', 'reviewed'),
  ('batch4-057', 'Hydra of the Black Deep', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'An unreasonable number of teal-lit heads, each biting a different one of you and living off the difference; it hunts groups for the variety.', 'reviewed'),
  ('batch4-058', 'Brineshade Drake', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'A wave with a shadow under it, fighting by rearrangement, yanking your fastest to the back with the patience of cold water that knows you must breathe.', 'reviewed'),
  ('batch4-059', 'Abyssridge Kaiju', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'The Coil''s heavyweight assassin, faster than its mass has any right to be, surfacing from a direction your shield wasn''t pointing; bring a roof.', 'reviewed'),
  ('batch4-060', 'Gravewater Serpent', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Ouranos', 'assassin', NULL, NULL, NULL, ARRAY['dragon', 'apex']::text[], 'The Coil''s closer, colour of water nobody resurfaces from, drifting in after the work is done to collect what''s left, swiftly and without comment.', 'reviewed'),
  ('batch4-061', 'Mirepyre Behemoth', 'batch4', NULL, 'organic', 'legendary', NULL, 'Eros', 'Thanatos', 'support', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'A walking bog that committed too hard to being alive; it knits your wounded shut and makes your enemies itch, both technically true, no contradiction seen.', 'reviewed'),
  ('batch4-062', 'Rotwood Stag-Colossus', 'batch4', NULL, 'organic', 'legendary', NULL, 'Eros', 'Thanatos', 'support', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'A stag the size of a wrong idea, antlers a hanging garden of luminous rot, pulling vitality from the dying and reseeding it green on your side.', 'reviewed'),
  ('batch4-063', 'Plaguescale Wallcrawler', 'batch4', NULL, 'organic', 'legendary', NULL, 'Eros', 'Thanatos', 'support', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'A hill that grew a bad mood and a digestive system; it plants over your wounded and dares the enemy through the fever-cloud. Safe like a quarantine tent.', 'reviewed'),
  ('batch4-064', 'Verdant Carrion-Wing', 'batch4', NULL, 'organic', 'legendary', NULL, 'Eros', 'Thanatos', 'support', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'A vulture that decided to be helpful, circling to grow your dead back into something approximately alive. The favour is genuine; the favour also itches.', 'reviewed'),
  ('batch4-065', 'Slagheart Bastion', 'batch4', NULL, 'construct', 'wild', 'T3', 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['construct']::text[], 'A walking fortress built around a green furnace-heart by hands that wanted a relocatable wall: it doesn''t eat, sleep, fear, or much think — it occupies space and refuses to surrender it.', 'reviewed'),
  ('batch4-066', 'Verdigris Reaper', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Eros', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'Old-copper green left out centuries to brood; it does not hurry a kill but wraps, waits, and grows healthier as you grow less so. The Mirepyre''s dark mirror.', 'reviewed'),
  ('batch4-067', 'Chitinghast Stalker', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Eros', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'A nightmare of elbows and edges, joint-lit from rotting within, skewering whatever you were protecting because it correctly guessed that''s worth killing.', 'reviewed'),
  ('batch4-068', 'Pallid Hunt-Hound', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Eros', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'A hound built like a famine, running ahead to mark a chosen victim with a death-sign only its clade can see. It picks; the Reapers collect.', 'reviewed'),
  ('batch4-069', 'Wyrmrot Dragon', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Eros', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'Wings rotted halfway, flying out of sheer refusal, dropping on one target like a falling graveyard and getting up healthier than it landed.', 'reviewed'),
  ('batch4-070', 'Hollow Sentinel-Wraith', 'batch4', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Eros', 'assassin', NULL, NULL, NULL, ARRAY['eldritch', 'apex']::text[], 'A gallows that learned to float, draped in what might be robes or prior visitors; it guards nothing and simply punishes motion. Stillness is the only mercy.', 'reviewed'),
  ('batch4-071', 'Sepulchre Cantor', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'A lich worn thin as a held breath; it does not scream but intones, slowing the field to a funeral''s pace and setting the key the whole choir waits for.', 'reviewed'),
  ('batch4-072', 'Mourner of the Long Halls', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'A grief-shape that forgot which death it set out to mourn and now mourns everyone, veiling foes in second-hand sorrow until they can barely lift their arms.', 'reviewed'),
  ('batch4-073', 'Choir-Shade Soprano', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'The choir''s highest voice, frozen mid-reach of a note it never finishes; its song deals no damage, it simply makes the enemy late until late turns fatal.', 'reviewed'),
  ('batch4-074', 'Threnody Warden', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'The Sepulchre''s bass and bodyguard, broad enough to let harm break on its shrouds; it guards the choir like a tombstone guards a name, already grieving you.', 'reviewed'),
  ('batch4-075', 'Pale Keening Spirit', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'A drowned draught that floats upward from habit; its keening does not roar but erodes, a ceaseless wearing-away that makes the strong feel briefly mortal.', 'reviewed'),
  ('batch4-076', 'Grave-Veiled Antiphon', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'A lich mourning in two mirrored voices, draping overlapping grey protection; cut off one voice and the other only sings louder. Worse to interrupt than watch.', 'reviewed'),
  ('batch4-077', 'Hollow Choirmaster', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'A lich with the bearing of one who ran a cathedral and never accepted the resignation; a sweep of pale arms forces the battlefield into his grim tempo.', 'reviewed'),
  ('batch4-078', 'Drowned Requiem-Singer', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'The voice that names the Drown-Choir, a lich that died underwater and never stopped pouring, settling a sodden weight on foes until moving feels like swimming.', 'reviewed'),
  ('batch4-079', 'Ashen Psalm-Wraith', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'Hung with ribbons of half-remembered scripture, each verse forbidding the enemy a move, a moment, a mercy, with the dry authority of a rule no one recalls passing.', 'reviewed'),
  ('batch4-080', 'Sovereign of the Silent Pews', 'batch4', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Thanatos', 'control', NULL, NULL, NULL, ARRAY['spirit', 'eldritch']::text[], 'The choir''s crowned sovereign, ruling a congregation that died facing the altar; when it raises the silence, the battlefield becomes a held funeral service.', 'reviewed'),
  ('batch4-081', 'Sproutling Drakelet', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A dragon the size of a loaf — all eyes, frills, and unearned confidence — that heals friends by good intent and bites with teeth that don''t yet work. Respect the try.', 'reviewed'),
  ('batch4-082', 'Violet Wyrmkit', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A purple hatchling that appointed itself the team''s emotional support, application or not. It chirps encouragement before every fight, even ones it can''t help with, and somehow everyone''s a half-step faster.', 'reviewed'),
  ('batch4-083', 'Dewdrop Pollen-Pup', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A blue dollop with one bobbing antenna for finding sad people, producing healing dew from no identifiable organ and applying it to creatures that didn''t ask to be damp.', 'reviewed'),
  ('batch4-084', 'Tidefin Seahatchling', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A finger-length seahorse-dragon taking its self-appointed lifeguard duties with total seriousness. It throws up a little spray-shield for friends, then looks around for the praise it has earned and should receive.', 'reviewed'),
  ('batch4-085', 'Glimmerwing Grub', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A grub with useless wing-buds and a face engineered to prevent squashing, defending the squad by sneezing glitter at enemies — which sounds useless and somehow isn''t. Give it a season.', 'reviewed'),
  ('batch4-086', 'Mothlight Faewing', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A moth-fae the colour of moonlight, wings patterned like eyes never quite finished, drawn to light and danger equally and weaponising it by being the most distracting thing on the field.', 'reviewed'),
  ('batch4-087', 'Mossgill Axolittle', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A purple axolotl baby whose philosophy is that nothing''s really broken if you wait and stay damp; it heals friends slowly and totally, having regrown most of itself once.', 'reviewed'),
  ('batch4-088', 'Skydown Chicklet', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A downy blue chick between songbird and griffin, fully committed to the idea it can already fly: it throws itself off things, fails upward, and kicks up a gust that genuinely helps.', 'reviewed'),
  ('batch4-089', 'Twinkle Faekit', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A winged kitten-fae that treats combat as a fancier string to chase, swatting little lights at enemies and dust motes alike — and on the ones that land, the squad''s luck ticks upward.', 'reviewed'),
  ('batch4-090', 'Pale Fawnling', 'batch4', NULL, 'organic', 'wild', 'T1', 'Eros', 'Ouranos', 'support', NULL, NULL, NULL, ARRAY['base', 'fae']::text[], 'A wobbly-legged fawn so pale it looks half-drawn, surviving by being faster than its terror and kinder than its odds — and, the faithful whisper, perhaps a very junior Pale-Hart relative.', 'reviewed'),
  ('batch4-091', 'Prism Wyrm', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'A dragon grown like a struck geode that doesn''t breathe fire but *refraction* — where the shards land, the ground is briefly a cathedral window and then a crater.', 'reviewed'),
  ('batch4-092', 'Spectral Facet-Drake', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'A dragon armoured in sapphire shards it sheds and regrows like a slow blizzard, flinging handfuls of itself at problems — so being attacked is gorgeous right until it isn''t.', 'reviewed'),
  ('batch4-093', 'Glasswing Lattice-Drake', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'A dragon with stained-glass wings someone diagrammed before they grew, every vein deliberate. It fights by *angles* — turning attacks aside with the cold precision of a proof and returning them refracted.', 'reviewed'),
  ('batch4-094', 'Iridescent Faewyrm', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'The clade''s most delicate-looking member, half-made of the light it bends. Don''t be charmed: the gleam is a weapon, and it detonates the rainbow at point-blank with a smile. Simply *vanity, armed*.', 'reviewed'),
  ('batch4-095', 'Aurora Geist-Drake', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'A crystal dragon caught between solid and sky, trailing colour like an aurora that grew teeth; it half-dissolves so strikes pass through, then answers with cascading, confusing light.', 'reviewed'),
  ('batch4-096', 'Opaline Wisp-Wyrm', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'A dragon the colour of opal held to a candle, all milky fire and drifting fins — it looks like the clade''s most peaceable member, then goes off like a flashbang when you relax.', 'reviewed'),
  ('batch4-097', 'Sapphire Storm-Wyrm', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'The clade''s tempest — a sapphire dragon that fights like weather, flinging a whole season of razor-sleet off its wings: loud, bright, and over very quickly for whoever it lands on.', 'reviewed'),
  ('batch4-098', 'Amethyst Maw-Wyrm', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'The bruiser of the crystal clade, a broad amethyst dragon that answered "how do I deal more damage" with a quarry of teeth, closing its jaws where its kin scatter light.', 'reviewed'),
  ('batch4-099', 'Violet Crystalfang Stalker', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'The clade''s prowler — built less like a dragon than a great cat carved from violet quartz — that picks one target and commits with fangs that splinter on contact and keep cutting.', 'reviewed'),
  ('batch4-100', 'Galaxis Prime-Wyrm', 'batch4', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['mystic', 'crystal']::text[], 'The grandest crystal, faceted hide dusted with trapped stars as if it swallowed a small night sky: where its kin scatter, this one *focuses*, pulling all that brilliance into a single apocalyptic point.', 'reviewed'),
  ('batch5-001', 'Boulderback', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A creature that solved being attacked by becoming geology; it does not dodge or plan, it lowers itself and lets the day break against its back.', 'reviewed'),
  ('batch5-002', 'Scoriad', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'Named for the black rock left when something burns then sulks; its little wings don''t fly so much as let it fall, with opinions, onto what annoyed it.', 'reviewed'),
  ('batch5-003', 'Tuskmire', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A boar that wears the swamp like armour and treats hygiene as a weakness in others; it plants in the muck and dares the fight to come wade for it.', 'reviewed'),
  ('batch5-004', 'Brackenbuck', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A buck that decided antlers were for blocking, not vanity; it stands its ground with the dim total conviction of underbrush — you go around, it wins.', 'reviewed'),
  ('batch5-005', 'Slategore', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A low grey wall someone unwisely gave a temper and a swing; it walks like furniture holding a grudge and delivers others to "out of the way."', 'reviewed'),
  ('batch5-006', 'Mosshackle', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A beast so overgrown it qualifies as habitat — birds nest in its hackles; it holds a line by being a deeply unpleasant thing to grab, hug, or bite.', 'reviewed'),
  ('batch5-007', 'Sigilcrest', 'batch5', NULL, 'organic', 'wild', 'T2', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['mixed']::text[], 'A frilled drake that treats a battlefield''s chaos as a clerical error to correct; it does not burn things, it files them, until the fight obeys procedure.', 'reviewed'),
  ('batch5-008', 'Lodewarden', 'batch5', NULL, 'organic', 'wild', 'T2', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['mixed']::text[], 'A slab-shouldered warden that stands at true vertical and judges everything that isn''t; it controls a fight by sheer immovable correctness.', 'reviewed'),
  ('batch5-009', 'Calcithorn', 'batch5', NULL, 'organic', 'wild', 'T2', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['mixed']::text[], 'A horned thing whose antlers grew in perfect crystal lattices, which it takes as proof the universe agrees; it pins foes in tidy mineral cages, puzzled they object.', 'reviewed'),
  ('batch5-010', 'Glyphwood', 'batch5', NULL, 'organic', 'wild', 'T2', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['mixed']::text[], 'A mossy stag carved over by glyphs it grew rather than learned; it treats a clearing as a contract and trespass as a breach litigated by underbrush.', 'reviewed'),
  ('batch5-011', 'Prismveil', 'batch5', NULL, 'organic', 'wild', 'T2', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['mixed']::text[], 'A white dragon that bends harm the way glass bends a sunbeam — coolly, precisely, as if the whole business is beneath it; bloodless and quietly insufferable.', 'reviewed'),
  ('batch5-012', 'Quartzwyrm', 'batch5', NULL, 'organic', 'wild', 'T2', 'Cosmos', 'Gaia', 'control', NULL, NULL, NULL, ARRAY['mixed']::text[], 'A slate-grey wyrm whose scales half-turned to mineral and whose temperament finished the job; it manages a battlefield like a magistrate manages a queue.', 'reviewed'),
  ('batch5-013', 'Glimmerune', 'batch5', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'A pale fox whose tail leaks a kind, cold light it seems embarrassed to produce; it tends the wounded with the manner of a nurse who has seen worse.', 'reviewed'),
  ('batch5-014', 'Goldglim', 'batch5', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'A fox dressed in tails of slow gold light, with the unbothered glamour of a thing that never worried about money or mortality; being its favourite is wonderful, earning it a fool''s errand.', 'reviewed'),
  ('batch5-015', 'Dawnlop', 'batch5', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'A hare whose ears catch the first light of any morning and pass it, warm, to whoever needs it most; it has quietly out-survived every flashier creature.', 'reviewed'),
  ('batch5-016', 'Lilastra', 'batch5', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'A lavender kitsune whose presence makes a battlefield go drowsy and strange; it guards its charges by convincing the violence to lose its train of thought.', 'reviewed'),
  ('batch5-017', 'Radihorn', 'batch5', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'A horned wolf that herds the wounded behind itself with the bossiness of a sheepdog; its halo is a budget of grace, spent carefully, refilled slowly.', 'reviewed'),
  ('batch5-018', 'Solivex', 'batch5', NULL, 'organic', 'wild', 'T2', 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'The oldest, most composed of the gold-tailed foxes, with the authority of something that has comforted many deaths; it simply tends, for as long as the fight lasts.', 'reviewed'),
  ('batch5-019', 'Rimegale', 'batch5', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'A frost-serpent that flies like weather with a grudge — it is simply already there, and you are simply already colder; it opens fights, never closes them.', 'reviewed'),
  ('batch5-020', 'Glaciel', 'batch5', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'A frost-deer so light it seems a rumour of cold rather than a body; it strikes the way a draft cuts, then is somewhere else, leaving ice and confusion.', 'reviewed'),
  ('batch5-021', 'Cryostorm', 'batch5', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'A blue dragon that does not ride storms so much as be one with teeth; it blinds before it bites, filling the air until the enemy swings at memories.', 'reviewed'),
  ('batch5-022', 'Hailrend', 'batch5', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'A slate-winged dragon with the disposition of falling ice and roughly the warmth; it dives, rends, and is climbing again before the wound registers.', 'reviewed'),
  ('batch5-023', 'Zephrime', 'batch5', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'A frost-rider built out of the cold edge of a fast wind — present, biting, and already past; it opens the fight by being faster than the argument.', 'reviewed'),
  ('batch5-024', 'Blackrime', 'batch5', NULL, 'organic', 'wild', 'T2', 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'The black dragon of the winter flight, all the cold with none of the courtesy of glittering; where its kin announce the storm, this one finishes it.', 'reviewed'),
  ('batch5-025', 'Empyriel', 'batch5', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['celestial']::text[], 'Descends only to correct an offense it calls a battle, rearranging who acts and when with bored, pre-ancient authority.', 'reviewed'),
  ('batch5-026', 'Astraveil', 'batch5', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['celestial']::text[], 'A night-sky watcher who edits what each side can be sure of; your aim finds after-images while it stays unknowable.', 'reviewed'),
  ('batch5-027', 'Aureon', 'batch5', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['celestial']::text[], 'A winged hart wearing a crown of cold light, refereeing endings and imposing peace without asking the violence first.', 'reviewed'),
  ('batch5-028', 'Throneward', 'batch5', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['celestial']::text[], 'The host''s last resort, planting an immovable throne over what must not fall and daring the battle to break on the floor.', 'reviewed'),
  ('batch5-029', 'Argentveil', 'batch5', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['celestial']::text[], 'A drake of running silver light that owns a fight''s rhythm, mireing the swift and keeping initiative as a ledger.', 'reviewed'),
  ('batch5-030', 'Caelumwyrm', 'batch5', NULL, 'organic', 'legendary', NULL, 'Cosmos', 'Ouranos', 'control', NULL, NULL, NULL, ARRAY['celestial']::text[], 'A heaven-serpent that shields by enclosing, wrapping allies in cold high light the battlefield''s worst can''t reach.', 'reviewed'),
  ('batch5-031', 'Magmakin', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['fierce']::text[], 'The runt of the fire-herd, which here means it explodes slightly less than its siblings and resents it; it detonates everything it has, then deals with the consequences badly.', 'reviewed'),
  ('batch5-032', 'Pyrebrand', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['fierce']::text[], 'A bull on fire and entirely at peace with it, treating "charge" as the answer to questions no one asked; magnificent, unstoppable, a hazard to its own herd.', 'reviewed'),
  ('batch5-033', 'Cindergryph', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['fierce']::text[], 'A griffin made of bonfire and bad judgment, which combines into a creature that solves problems by falling on them while alight; loyal enough, tensely.', 'reviewed'),
  ('batch5-034', 'Ashthorn', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['fierce']::text[], 'A stag whose antlers caught fire one season and never went out, which it considers an upgrade; it walks a crown of torches through the enemy line.', 'reviewed'),
  ('batch5-035', 'Magmagore', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['fierce']::text[], 'A boar with tusks that glow like fresh slag and a temperament to match; it gores upward, which is rude, and the wounds cook closed wrong.', 'reviewed'),
  ('batch5-036', 'Cindermane', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['fierce']::text[], 'A lion wearing a mane of open flame, loudest and proudest of an immodest herd; it opens fights with a wall of fire, then treats being on fire as a later issue.', 'reviewed'),
  ('batch5-037', 'Magmoloch', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'A walking magma cliff that erupts at you rather than attacks, cracking the earth open; the death in its fire is the quiet part.', 'reviewed'),
  ('batch5-038', 'Ashreaver', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'A starved blade-limbed fiend that harvests endings, growing keener with every soul it takes. Nothing about it is wasted.', 'reviewed'),
  ('batch5-039', 'Cindergeist', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'An armored demon with a furnace where its grudge should be, overloading until everything nearby burns, including its composure.', 'reviewed'),
  ('batch5-040', 'Pyrabaddon', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'A winged ruin that descends like bad news; where it lands the fight is a formality, death in the heat, arrogance in all else.', 'reviewed'),
  ('batch5-041', 'Sunderwail', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'A demon shaped like a collapsing roof, splitting its own form to double the scream that empties the front rank.', 'reviewed'),
  ('batch5-042', 'Maledict', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'Takes up cursing like gardening, naming you guilty in a flat clerical mutter and bleeding your defenses to nothing over days.', 'reviewed'),
  ('batch5-043', 'Pallcreep', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Cosmos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A pale, patient thing that haunts the edge of your vision and the front of your insurance claims; it waits, warded, until the target tires of looking.', 'reviewed'),
  ('batch5-044', 'Duskmantle', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Cosmos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A wraith that wears the evening like a borrowed coat and keeps the pockets; it folds its wings around a victim and the world goes politely, terminally quiet.', 'reviewed'),
  ('batch5-045', 'Hollowarden', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Cosmos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A heavy, hollow sentinel that took a guard''s post after the guard left and never resigned; it does not pursue, it occupies, and you may not pass without donating.', 'reviewed'),
  ('batch5-046', 'Veilwane', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Cosmos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A fading thing that takes the world down one degree at a time; nothing about its attack is dramatic — you simply notice, eventually, there is less of you.', 'reviewed'),
  ('batch5-047', 'Umbracoil', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Cosmos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'The Wisps'' serpent, a coil of darkness that hunts by being impossible to shrug off; it latches, waits, and grows stronger from the panic.', 'reviewed'),
  ('batch5-048', 'Gloamveil', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Cosmos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A shade so composed it makes the dark look organized; it draws the gloom shut like a stage curtain and conducts the killing from the dark side of it.', 'reviewed'),
  ('batch5-049', 'Pyreghast', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'An ash-grey demon that flies to funerals uninvited and improves attendance by adding to the guest list, then detonating.', 'reviewed'),
  ('batch5-050', 'Glorivore', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'The Brood''s most beautiful liar, a false-holy radiance that eats anything that kneels and bills like a loan shark.', 'reviewed'),
  ('batch5-051', 'Carrionlord', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'A plated demon built like a tax, arriving once the dying starts to collect with a flooded-landlord''s entitlement.', 'reviewed'),
  ('batch5-052', 'Tendrilbane', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'Mostly arms and entirely opinions, delivering a beating by committee where each tendril feuds over whom to hit first.', 'reviewed'),
  ('batch5-053', 'Houndsorrow', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'A grief that grew teeth from being left in the cold, howling like a slammed door you feel through the floor.', 'reviewed'),
  ('batch5-054', 'Nocturnex', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Thanatos', 'nuker', NULL, NULL, NULL, ARRAY['demon']::text[], 'The last-hatched and worst-tempered, a serpent that gave the dark a spine; it moves like rumor and lands like a verdict.', 'reviewed'),
  ('batch5-055', 'Squallmaw', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Thanatos', 'striker', NULL, NULL, NULL, ARRAY['aquatic']::text[], 'A finned horror quick as a squall, striking twice before the water finishes parting, the second blow carrying drowned rot.', 'reviewed'),
  ('batch5-056', 'Brineflense', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Thanatos', 'striker', NULL, NULL, NULL, ARRAY['aquatic']::text[], 'A grievance with too many legs that doesn''t pinch so much as file you down, one quick stripping cut at a time.', 'reviewed'),
  ('batch5-057', 'Maelkraken', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Thanatos', 'striker', NULL, NULL, NULL, ARRAY['aquatic']::text[], 'A kraken that mistook ambush predator for being everywhere at once; its eight arms arrive on their own schedule, which is now.', 'reviewed'),
  ('batch5-058', 'Inkrender', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Thanatos', 'striker', NULL, NULL, NULL, ARRAY['aquatic']::text[], 'A squid the colour of a drowning and twice as quick, clouding the water then carving it in a dark it brought.', 'reviewed'),
  ('batch5-059', 'Fathomdread', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Thanatos', 'striker', NULL, NULL, NULL, ARRAY['aquatic']::text[], 'A horror that hauled the sea''s crushing bottom up like a held breath, arriving at speed and without asking permission.', 'reviewed'),
  ('batch5-060', 'Wraithtide', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Thanatos', 'striker', NULL, NULL, NULL, ARRAY['aquatic']::text[], 'The palest Drownkith, a tide that kept walking after the water left, drifting in like fog and striking like surf.', 'reviewed'),
  ('batch5-061', 'Cairnhide', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A beast that wears the cemetery on its back and a graveyard''s patience in its skull; it simply outweighs the problem until the problem stops.', 'reviewed'),
  ('batch5-062', 'Wyrmbarrow', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A squat earth-dragon that gave up flying for the surer dignity of not moving; it anchors like a buried thing and makes its problems join it underground.', 'reviewed'),
  ('batch5-063', 'Mournfleece', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A black ram heavy enough to settle an argument by leaning on it, draped in wool that smells of cold churchyards; gentle until crowded, then geology.', 'reviewed'),
  ('batch5-064', 'Sepulchrab', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A land-crab that grew a carapace like a sealed crypt and a temperament to match; it does not retreat into its shell, it invites you to break against it.', 'reviewed'),
  ('batch5-065', 'Direbarrow', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A wolf built less for the hunt than for standing immovably over the result of one; loyal past reason, and past the point the guarded thing can appreciate.', 'reviewed'),
  ('batch5-066', 'Lichbristle', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Thanatos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A bristled boar that has rooted in too many old battlefields and started to smell of them; it does not charge, it settles, half-rooted already.', 'reviewed'),
  ('batch5-067', 'Emberbristle', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A spiteful hog whose bristles smoulder when its mood does, which is most mealtimes; it would rather hold ground than take it — but will, if you stand on the good roots.', 'reviewed'),
  ('batch5-068', 'Slagscale', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A young plated dragon-thing too stubborn to fly and too hot to hug; it plants itself like a paving slab with opinions and dares the day to move it.', 'reviewed'),
  ('batch5-069', 'Hornscorch', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A horned brute that meets every problem forehead-first and considers second thoughts a failing; the angrier and more battered it gets, the harder it hits.', 'reviewed'),
  ('batch5-070', 'Mossgut', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A deceptively soft-looking lump that is mostly muscle, grudge, and alarming density; it rolls into trouble with the cheerful gravity of a dropped anvil.', 'reviewed'),
  ('batch5-071', 'Grubbletusk', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A stout digging hog that treats turf the way a tantrum treats a tidy room; it charges in a spray of upturned earth, half attack, half landscaping disaster.', 'reviewed'),
  ('batch5-072', 'Snarlmound', 'batch5', NULL, 'organic', 'wild', 'T2', 'Gaia', 'Chaos', 'tank', NULL, NULL, NULL, ARRAY['beast']::text[], 'A broad, grudging brute that picks a hill and a hatred and commits to both for life; not fast, clever, or negotiable — simply there, the wrong place to be.', 'reviewed'),
  ('batch5-073', 'Chromestag', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['metallic']::text[], 'A stag forged, or grown, in chrome — nobody will commit to which — and bright enough to shave in; it guards by reflection, sending your worst impulses back.', 'reviewed'),
  ('batch5-074', 'Brasshorn', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['metallic']::text[], 'A gilded ram whose horns ring like a cathedral when struck, which it finds dignified and its enemies find concussive; it sounds a note that unnerves violence.', 'reviewed'),
  ('batch5-075', 'Quicksilverene', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['metallic']::text[], 'A beast sheathed in something between metal and water, so blows seem to decide against it mid-swing; heavy as a casting, yet shrugs like a ripple.', 'reviewed'),
  ('batch5-076', 'Pewterhound', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['metallic']::text[], 'A patient, matte-silver hound that takes "stand in front of the squishy one" as scripture; not flashy, but the one still standing when the flashy ones are dented.', 'reviewed'),
  ('batch5-077', 'Argentwyrm', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['metallic']::text[], 'A silver wyrm that decided being beautiful and immovable beat being fast and on fire; it curls mirrored wings around the squad like a vault door easing shut.', 'reviewed'),
  ('batch5-078', 'Cobaltsheen', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Cosmos', 'tank', NULL, NULL, NULL, ARRAY['metallic']::text[], 'The bluest and most stubborn of the Host, tempered like a sword-edge and as eager to bend; it only gets harder to crack the longer you try.', 'reviewed'),
  ('batch5-079', 'Venomcourt', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A scorpion the colour of a bruise, armoured like a verdict and twice as final; it strikes once and lets arithmetic finish, the poison compounding like a debt.', 'reviewed'),
  ('batch5-080', 'Shadefletch', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A lean shadow with too many edges, half assassin and half ambush; it does not duel, it salvos — barbs from the dark, gone before the count.', 'reviewed'),
  ('batch5-081', 'Sablewing', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A raven that ate a small dragon and kept the worst habits of both; every feather honed to an edge, it does not circle prey so much as audit it, fatally.', 'reviewed'),
  ('batch5-082', 'Hornblack', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A ram that grazed in a graveyard until the graveyard grazed back, and now wears that bargain on its horns; it charges with a debt collector''s patience.', 'reviewed'),
  ('batch5-083', 'Coilgloam', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A serpent that grew extra heads the way a liar grows extra stories — to keep one occupied while the others work; you will swear you''re watching all of it. You''re not.', 'reviewed'),
  ('batch5-084', 'Cinderboar', 'batch5', NULL, 'organic', 'wild', 'T3', 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'A boar with one eye long gone out and one that won''t, and it has never forgiven the difference; it hunts the biggest thing in the clearing, on principle.', 'reviewed'),
  ('batch5-085', 'Mantissable', 'batch5', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'Scythe-armed mantis that folds in mock prayer, then unfolds into your back line; every kill it lands sharpens the next reaping.', 'reviewed'),
  ('batch5-086', 'Scarabnox', 'batch5', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'Grave-beetle that rolls the unburied into a withering cloud, draining what it touches and growing fatter the longer the slaughter runs.', 'reviewed'),
  ('batch5-087', 'Pallpanther', 'batch5', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'Panther stitched from 3 a.m. dark, striking first and unseen; if it kills, it slips back into shadow and the next kill comes free.', 'reviewed'),
  ('batch5-088', 'Direhusk', 'batch5', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'Armored ambush-slab that looks like terrain, then locks its jaw on one throat and drains harder the longer it refuses to let go.', 'reviewed'),
  ('batch5-089', 'Vesperdrake', 'batch5', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'Bruise-colored drake that stoops from the dark for a staggering dive, magnificent in descent and fatal to whoever the landing finds.', 'reviewed'),
  ('batch5-090', 'Mourningmare', 'batch5', NULL, 'organic', 'legendary', NULL, 'Thanatos', 'Chaos', 'assassin', NULL, NULL, NULL, ARRAY['dark']::text[], 'Pale death-courier that glides the line dealing Bane and dragging the struck toward the back, offering everyone a ride they won''t return from.', 'reviewed'),
  ('batch5-091', 'Glacewyrm', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'First-frost serpent that glazes the room and lands three lashes ahead of the shiver, slowing all it touches before the cold even arrives.', 'reviewed'),
  ('batch5-092', 'Frostfawn', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'Thin-ice darter that never falls, bursting ahead to lend the squad its rush and lay a sliver of frost-Ward over everyone.', 'reviewed'),
  ('batch5-093', 'Hoarhart', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'Antlered stag goring with the brisk efficiency of weather, striking early and frost-locking pinned prey where the silence is total.', 'reviewed'),
  ('batch5-094', 'Rimelion', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'Lion frozen mid-roar and permanently furious, pouncing first to chill its prey and shave their speed before they can answer.', 'reviewed'),
  ('batch5-095', 'Sleetquill', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'Blizzard-chimed bird crossing the field faster than its own cold, clipping two front targets before either reacts and molting icicles as it goes.', 'reviewed'),
  ('batch5-096', 'Frostfen Vixen', 'batch5', NULL, 'organic', 'legendary', NULL, 'Ouranos', 'Cosmos', 'striker', NULL, NULL, NULL, ARRAY['frost']::text[], 'Frost-fox of nine crystalline tails, one move ahead always, stacking evasion while it dances; catching it is like catching your reflection.', 'reviewed'),
  ('batch5-097', 'Geodecrane', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['crystal']::text[], 'Faceted crystal-crane holding its neck like a loaded prism, firing a splitting light-lance when the angle pleases it, rarely and devastatingly.', 'reviewed'),
  ('batch5-098', 'Prismcoil', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['crystal']::text[], 'More window than wyrm, it hoards light then spends it in one chiming detonation that leaves the air full of glittering regret.', 'reviewed'),
  ('batch5-099', 'Facetflit', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['crystal']::text[], 'Stained-glass scalpel on wings; it molts razor edges and beats them into the whole line, the already-wounded catching the worst shrapnel.', 'reviewed'),
  ('batch5-100', 'Jadefang', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['crystal']::text[], 'Crystal-lizard whose smile keeps adding teeth, biting and biting until the geometry of its jaw becomes everyone''s problem.', 'reviewed'),
  ('batch5-101', 'Spinegeode', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['crystal']::text[], 'Walking pincushion with opinions, launching its own back at you and regrowing it, an arms race it always wins against itself.', 'reviewed'),
  ('batch5-102', 'Geodewrath', 'batch5', NULL, 'organic', 'legendary', NULL, 'Chaos', 'Cosmos', 'nuker', NULL, NULL, NULL, ARRAY['crystal']::text[], 'Slab of dark crystal with a grudge in its chest, lighting its own fuse for one colossal core-blast and standing there smug while it recharges.', 'reviewed'),
  ('batch5-103', 'Mossgrobble', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Eros', 'tank', NULL, NULL, NULL, ARRAY['earth']::text[], 'A boulder that grew a wide mouth and a wider sense of belonging; it tanks hits by simply not acknowledging them, and the moss on its back pays no rent.', 'reviewed'),
  ('batch5-104', 'Carapyle', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Eros', 'tank', NULL, NULL, NULL, ARRAY['earth']::text[], 'An earth-beetle the size of a doorway and about as eager to leave one; its shell is layered like sediment — each season adds a plate and a grudge.', 'reviewed'),
  ('batch5-105', 'Crag Bull', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Eros', 'tank', NULL, NULL, NULL, ARRAY['earth']::text[], 'A bull carved out of a hillside that took "immovable object" as a personal goal and met it; it becomes, briefly, geography, and finds being broken upon restful.', 'reviewed'),
  ('batch5-106', 'Bouldergrip', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Eros', 'tank', NULL, NULL, NULL, ARRAY['earth']::text[], 'A stone troll with arms long enough to hug a problem until it stops, and the patience to mean it; it does not punch, it gathers you up and waits.', 'reviewed'),
  ('batch5-107', 'Quarryscorn', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Eros', 'tank', NULL, NULL, NULL, ARRAY['earth']::text[], 'An armoured digger that decided the safest place in any fight is exactly where it''s standing; it anchors into the earth and dares the battle to relocate it.', 'reviewed'),
  ('batch5-108', 'Geargle Hulk', 'batch5', NULL, 'organic', 'wild', 'T3', 'Gaia', 'Eros', 'tank', NULL, NULL, NULL, ARRAY['earth']::text[], 'A hill with legs and a back full of slow-growing crystal it treats as a garden; it tucks in, becomes terrain, and the squad shelters in its lee.', 'reviewed'),
  ('batch5-109', 'Gildgrub', 'batch5', NULL, 'organic', 'legendary', NULL, 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'Fat radiant grub humming hymns it shouldn''t know, cocooning the most-wounded in gilded silk and healing everything it inches past, foes included.', 'reviewed'),
  ('batch5-110', 'Aureate Wyrm', 'batch5', NULL, 'organic', 'legendary', NULL, 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'Dragon that looks minted rather than hatched, blessing the whole squad at once and gilding the dying in a temporary Ward shell.', 'reviewed'),
  ('batch5-111', 'Haloquill', 'batch5', NULL, 'organic', 'legendary', NULL, 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'Winged saint who canopies the squad in ordered light, smoothing the worst dice into something survivable and pitying your panic.', 'reviewed'),
  ('batch5-112', 'Goldhart', 'batch5', NULL, 'organic', 'legendary', NULL, 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'Dawn-plated stag whose antlers branch into little suns; where it steps the wounded stand, serene while the enemy seethes.', 'reviewed'),
  ('batch5-113', 'Sanctum Colossus', 'batch5', NULL, 'organic', 'legendary', NULL, 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'Cathedral that learned to walk, planting itself amid the squad to bank every hit and discharge it back as grace on a liturgical schedule.', 'reviewed'),
  ('batch5-114', 'Empyrean Coil', 'batch5', NULL, 'organic', 'legendary', NULL, 'Eros', 'Cosmos', 'support', NULL, NULL, NULL, ARRAY['radiant']::text[], 'Serpent of pure dawn-light that loops the squad in a halo, healing without tiring and correcting death once like a clerical error.', 'reviewed'),
  ('batch5-115', 'Goldwrath Ram', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['golden']::text[], 'A ram cast in war-brass that confuses a closed door with a personal insult, then with rubble; the horns are inscribed with victories it cannot read.', 'reviewed'),
  ('batch5-116', 'Auric Behemoth', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['golden']::text[], 'A gold-plated brute whose every gesture is a demolition and whose every demolition is, to it, a hello; it hits the ground harder than it hits you.', 'reviewed'),
  ('batch5-117', 'Solquill', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['golden']::text[], 'A gilded bird that mistook itself for the sun and has been overcompensating ever since, mostly downward and on fire; altitude is its ammunition.', 'reviewed'),
  ('batch5-118', 'Bullion Drake', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['golden']::text[], 'A drake forged rather than hatched, lugging a furnace it is far too eager to open; it breathes liquid gold and considers the cleanup your concern.', 'reviewed'),
  ('batch5-119', 'Sunscale Wyrm', 'batch5', NULL, 'organic', 'wild', 'T3', 'Chaos', 'Gaia', 'nuker', NULL, NULL, NULL, ARRAY['golden']::text[], 'The sleekest, proudest sun-brute, a gold wyrm that swims the air like a blade and detonates like a vault; it finds brute force gauche and uses it anyway.', 'reviewed')
