insert into factions (id, name, region, god, grid, ideology) values
  ('concord', 'The Concord', 'Astral Tier', 'Athena/Apollo', 'Order / Pure', 'Refill the thrones lawfully; gods as cosmic civil service.'),
  ('iron_guild', 'The Iron Guild', 'Forgefell', 'Hephaestus', 'Order / Tainted', 'Build better gods than were born; ethics are an engineering constraint.'),
  ('pale_court', 'The Pale Court', 'Mournmarch', 'Hades', 'Order / Corrupt', 'Death is just unredeemed power; the bloodline-bank aristocracy.'),
  ('high_table', 'The High Table', 'Storm Vault', 'Zeus', 'Balanced', 'The brokers — contracts, markers, the rules between god-makers.'),
  ('stoneblooded', 'The Stoneblooded', 'Titanfall', '(dead Titan)', 'Balanced / Pure', 'Old clans; endurance, tradition, the husbandry way.'),
  ('bloomwardens', 'The Bloomwardens', 'Verdant Glut', 'Demeter', 'Pure', 'Life is sacred; tend, heal, befriend — never butcher.'),
  ('revel', 'The Revel', 'Verdant/Sunder', 'Dionysus', 'Chaos / Tainted', 'Ecstasy, indulgence, glorious mutation.'),
  ('unbound', 'The Unbound', 'The Sunder', 'Eris', 'Chaos / (any)', 'Burn every throne; let no god rule again.'),
  ('deep_choir', 'The Deep Choir', 'The Tideless', 'Poseidon', 'Balanced / Corrupt', 'The drowned remember; eldritch communion.')
